var t=[{title:`Waar polsbelasting vandaan komt`,text:`Push-ups en planken op vlakke handpalmen buigen de pols ver naar achteren. Oefeningen met dumbbells en barbells voegen grip- en stabilisatiewerk toe. Polsklachten hebben veel mogelijke oorzaken, en de oefening alleen kan je niet vertellen welke het is.`},{title:`Verander hoe je handen de vloer raken`,text:`Push-ups met verhoogde handen leggen minder van je gewicht op je armen. Stabiele push-uphandvatten of vastgezette dumbbells die niet kunnen rollen, laten je de pols rechter houden. Onderarmplanken nemen de druk van je handpalmen helemaal weg. Sommige mensen vinden ook een dumbbellpers met neutrale grip comfortabeler dan een pers met rechte stang.`},{title:`Houd de aanpassingen veilig`,text:`Gebruik nooit dumbbells die kunnen rollen als geïmproviseerde push-uphandvatten. Controleer of steunen stabiel zijn en het oppervlak niet kan wegglijden. Forceer een pijnlijke pols niet in een positie alleen omdat een techniekaanwijzing die ideaal noemt. Doet een beweging pijn, stop dan en zoek een comfortabel alternatief.`},{title:`Bouw langzaam op`,text:`Bouw totale herhalingen en controle op voordat je een zwaardere hefboom met lichaamsgewicht probeert. Ga naar een arts bij nieuwe pijn na een val, ernstige zwelling, misvorming, tintelingen of verlies van kracht. Blijven polsklachten bestaan, laat ze dan door een professional controleren, want TrainUp kan ze niet vaststellen.`},{title:`TrainUp gebruiken`,text:`Voeg je polsen toe als beperking in Profiel en vul je uitrusting in. Het schema kiest dan oefeningen die passen, waaronder mogelijk coreoefeningen op je onderarmen. Na een training kun je pijn melden met het lichaamsdeel en de oefening, en met de notities bijhouden hoe je polsen het deden. TrainUp bouwt geen revalidatieroutines.`}];var a=[{label:`NHS: gewrichtspijn`,url:`https://www.nhs.uk/symptoms/joint-pain/`},{label:`Standpunt van het ACSM uit 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var i={sections:t,sources:a};export{i as default,t as sections,a as sources};